import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;
import java.util.Collections;

public class Cutting {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int B = sc.nextInt();
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = sc.nextInt();
        }

        int countCuts = 0;
        int oddCount = 0;
        int evenCount = 0;
        List<Integer> maxDiffs = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (arr[i] % 2 == 0) {
                evenCount++;
            } else {
                oddCount++;
            }
            if (evenCount == oddCount && evenCount != 0 && i != n - 1) {
                int diff = Math.max(arr[i], arr[i + 1]) - Math.min(arr[i], arr[i + 1]);
                maxDiffs.add(diff);
            }
        }
        Collections.sort(maxDiffs);
        for (int d : maxDiffs) {
            if (B >= d) {
                countCuts++;
                B -= d;
            }
        }
        System.out.println(countCuts);
    }
}
