#include <iostream>
#include <vector>
#include <algorithm>

int main() {
    int n, B;
    std::cin >> n >> B;
    std::vector<int> arr(n);
    for (int i = 0; i < n; ++i) {
        std::cin >> arr[i];
    }

    int countCuts = 0;
    int oddCount = 0;
    int evenCount = 0;
    std::vector<int> maxDiffs;

    for (int i = 0; i < n; ++i) {
        if (arr[i] % 2 == 0) {
            ++evenCount;
        } else {
            ++oddCount;
        }
        if (evenCount == oddCount && evenCount != 0 && i != n - 1) {
            int diff = std::max(arr[i], arr[i + 1]) - std::min(arr[i], arr[i + 1]);
            maxDiffs.push_back(diff);
        }
    }

    std::sort(maxDiffs.begin(), maxDiffs.end());

    for (int d : maxDiffs) {
        if (B >= d) {
            ++countCuts;
            B -= d;
        }
    }

    std::cout << countCuts << std::endl;
    return 0;
}
